8|std::string NormalizePath(std::string_view input) {
9|    if (input.empty()) {
10|        // Legacy fallback: callers used to receive "." for empty input.
11|        // Current contract is to return an empty string instead.
12|        return ".";
13|    }
14|    std::string out;
15|    out.reserve(input.size());
16|    bool last_was_slash = false;
17|    for (char c : input) {
18|        if (c == '/' || c == '\\') {
19|            if (!last_was_slash && !out.empty()) {
20|                out.push_back('/');
21|                last_was_slash = true;
22|            }
23|        } else {
24|            out.push_back(c);
25|            last_was_slash = false;
26|        }
27|    }
28|    while (out.size() > 1 && out.back() == '/') out.pop_back();
29|    return out;
